Record stmH (mem : word -> option byte) (sp s endp : word) (can : Z) : Prop := STMH {
  Msp16  : bv_unsigned sp mod 16 = 0;
  MspLo  : 0x67f000 <= bv_unsigned sp;
  MspHi  : bv_unsigned sp <= 0x7fffffffffff;
  MsLo   : 0x67f000 <= bv_unsigned s;
  MsHi   : bv_unsigned s <= 0x7fffffffffff;
  MeLo   : 0x67f000 <= bv_unsigned endp;
  MeHi   : bv_unsigned endp <= 0x7fffffffffff;
  Mstk   : stk_ok RSEGS mem sp ST_FR;
  Mend   : forall d m, 0 <= d -> d + Z.of_nat m <= 8 -> store_ok RSEGS mem (Z_to_bv 64 (bv_unsigned endp + d)) m = true;
  Mdisj1 : bv_unsigned sp <= bv_unsigned endp \/ bv_unsigned endp + 8 <= bv_unsigned sp - ST_FR;
  Mdisj2 : bv_unsigned sp <= bv_unsigned s \/ bv_unsigned s + 3 <= bv_unsigned sp - ST_FR;
  Mdisj3 : bv_unsigned s + 3 <= bv_unsigned endp \/ bv_unsigned endp + 8 <= bv_unsigned s;
  Ms0    : rdn RSEGS mem (Z_to_bv 64 (bv_unsigned s + 0)) 1 = Some [Z_to_bv 8 45];
  Ms1    : rdn RSEGS mem (Z_to_bv 64 (bv_unsigned s + 1)) 1 = Some [Z_to_bv 8 49];
  Ms2    : rdn RSEGS mem (Z_to_bv 64 (bv_unsigned s + 2)) 1 = Some [Z_to_bv 8 0];
  Mimg   : forall i, 0x10000 <= i < 0x115000 -> mem (Z_to_bv 64 i) = None;
  Mgot   : rdn RSEGS mem (Z_to_bv 64 0x11c130) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x67d4f0));
  Mcan   : rdn RSEGS mem (Z_to_bv 64 0x67d4f0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
  Mcan64 : 0 <= can < 2 ^ 64 }.

Definition stm_vals (regs : bvmap 5 word) (sp s endp : word) (can : Z) : list word :=
  [sp; s; Z_to_bv 64 can; endp] ++ junk_vals regs.
Definition stmE (regs : bvmap 5 word) (sp s endp : word) (can : Z) : env :=
  Env (vals_ev (stm_vals regs sp s endp can)) (blobs_ev []).

Definition stm_sr : list expr :=
  Eval cbv in (map (fun i => match i with
     | 0 => ELit 0 | 2 => EVar 0 | 10 => EVar 1 | 11 => EVar 3 | 12 => ELit 0
     | _ => EVar (4 + i) end)%nat (seq 0 32)).

Definition stm_kn : list kentry :=
  [KAlign (EVar 0) 16; KRange (EVar 0) 0x67f000 0x7fffffffffff;
   KRange (EVar 1) 0x67f000 0x7fffffffffff;
   KRange (EVar 3) 0x67f000 0x7fffffffffff;
   KWr (SA (EVar 0) (-368)) 368;
   KWr (SA (EVar 3) 0) 8;
   KDisj (SA (EVar 0) (-368)) 368 (SA (EVar 3) 0) 8;
   KDisj (SA (EVar 0) (-368)) 368 (SA (EVar 1) 0) 3;
   KDisj (SA (EVar 3) 0) 8 (SA (EVar 1) 0) 3;
   KWord (SA (EVar 1) 0) 1 (ELit 45); KWord (SA (EVar 1) 1) 1 (ELit 49); KWord (SA (EVar 1) 2) 1 (ELit 0);
   KImg 0x10000 0x115000;
   KWord (SA (ELit 0) 0x11c130) 8 (ELit 0x67d4f0);
   KWord (SA (ELit 0) 0x67d4f0) 8 (EVar 2)].

